import { Buffer } from "node:buffer";
export default async function next({ baseUrl, owner, repo, path, channelId, acknowledge }, ctx) {
  if (
    !/^https:\/\//.test(baseUrl) ||
    baseUrl.includes("YOUR_") ||
    [owner, repo, channelId].some((x) => !x || x.includes("YOUR_"))
  )
    throw Error("Configure n8n URL, GitHub repository, and Slack channel");
  let s = await ctx.state.get("workflow-backup");
  if (!s) {
    s = {
      phase: "start",
      cursor: null,
      nextCursor: null,
      queue: [],
      index: 0,
      total: 0,
      failed: 0,
      pending: null,
    };
    await ctx.state.set("workflow-backup", s);
  }
  if (s.pending) {
    if (acknowledge !== s.pending) throw Error("Inspect external write " + s.pending);
    if (s.pending === "slack:start") s.phase = "list";
    else if (s.pending === "slack:complete") s.phase = "done";
    else if (s.pending.startsWith("slack:fail:")) {
      s.index++;
      s.phase = "item";
    } else if (s.pending.startsWith("github:")) {
      s.index++;
      s.phase = "item";
    }
    s.pending = null;
    await ctx.state.set("workflow-backup", s);
  }
  for (;;) {
    let action = s.phase,
      url = "https://api.github.com/",
      body = {},
      text = ".",
      item = s.queue[s.index];
    if (action === "item") {
      if (!item) {
        if (s.nextCursor) {
          s.cursor = s.nextCursor;
          s.nextCursor = null;
          s.phase = "list";
        } else s.phase = "complete";
        await ctx.state.set("workflow-backup", s);
        continue;
      }
      if (!item.id || !/^\d{4}-\d\d-/.test(item.createdAt ?? ""))
        throw Error("Workflow must include id and createdAt");
      s.filePath = path
        .replace(/^\/+|\/+$/g, "")
        .split("/")
        .filter(Boolean)
        .concat(item.createdAt.slice(0, 7).split("-"), String(item.id) + ".json")
        .map(encodeURIComponent)
        .join("/");
      s.phase = "get";
      await ctx.state.set("workflow-backup", s);
      continue;
    }
    if (action === "list")
      url =
        baseUrl.replace(/\/$/, "") +
        "/api/v1/workflows?limit=100" +
        (s.cursor ? "&cursor=" + encodeURIComponent(s.cursor) : "");
    if (action === "get" || action === "raw" || action === "write")
      url =
        "https://api.github.com/repos/" +
        encodeURIComponent(owner) +
        "/" +
        encodeURIComponent(repo) +
        "/contents/" +
        s.filePath;
    if (action === "write") {
      const sorted = Object.fromEntries(
        Object.entries(item).sort(([a], [b]) => a.localeCompare(b)),
      );
      body = {
        message: (item.name ?? item.id) + " (" + (s.sha ? "different" : "new") + ")",
        content: Buffer.from(JSON.stringify(sorted, null, 2)).toString("base64"),
        ...(s.sha ? { sha: s.sha } : {}),
      };
      s.pending = "github:" + item.id;
      await ctx.state.set("workflow-backup", s);
    }
    if (action === "start" || action === "complete" || action === "failure") {
      text =
        action === "start"
          ? "Starting workflow backup"
          : action === "complete"
            ? "Backup completed: " + s.total + " workflows; " + s.failed + " failed"
            : "Failed to back up workflow " + item.id;
      s.pending = action === "failure" ? "slack:fail:" + item.id : "slack:" + action;
      await ctx.state.set("workflow-backup", s);
    }
    if (action === "done") {
      await ctx.state.set("workflow-backup", null);
    }
    return { action, url, body, text, channelId };
  }
}

