import { Buffer } from "node:buffer";
async function result({ kind, statusCode, body }, ctx) {
  const s = await ctx.state.get("workflow-backup");
  if (!s) throw Error("Missing backup state");
  if (kind === "start") {
    s.pending = null;
    s.phase = "list";
  } else if (kind === "complete") {
    s.pending = null;
    s.phase = "done";
  } else if (kind === "failure") {
    s.pending = null;
    s.index++;
    s.phase = "item";
  } else if (kind === "list") {
    if (statusCode !== 200 || !Array.isArray(body.data)) throw Error("Cannot list n8n workflows");
    s.queue = body.data;
    s.index = 0;
    s.total += body.data.length;
    s.nextCursor = body.nextCursor ?? null;
    s.phase = "item";
  } else if (kind === "get") {
    if (statusCode === 404) {
      s.sha = null;
      s.phase = "write";
    } else if (statusCode === 200 && typeof body.sha === "string") {
      s.sha = body.sha;
      if (body.content) {
        s.existing = Buffer.from(body.content.replace(/\s/g, ""), "base64").toString("utf8");
        s.phase = "compare";
      } else s.phase = "raw";
    } else {
      s.failed++;
      s.phase = "failure";
    }
  } else if (kind === "raw") {
    if (statusCode === 200 && typeof body === "string") {
      s.existing = body;
      s.phase = "compare";
    } else {
      s.failed++;
      s.phase = "failure";
    }
  } else if (kind === "write") {
    if (statusCode === 200 || statusCode === 201) {
      s.pending = null;
      s.index++;
      s.phase = "item";
    } else if (statusCode >= 400 && statusCode < 500) {
      s.pending = null;
      s.failed++;
      s.phase = "failure";
    } else throw Error("Inspect uncertain GitHub write " + s.queue[s.index].id);
  }
  if (s.phase === "compare") {
    const sort = (x) =>
      JSON.stringify(Object.fromEntries(Object.entries(x).sort(([a], [b]) => a.localeCompare(b))));
    if (sort(JSON.parse(s.existing)) === sort(s.queue[s.index])) {
      s.index++;
      s.phase = "item";
    } else s.phase = "write";
    delete s.existing;
  }
  await ctx.state.set("workflow-backup", s);
  return { ok: true };
}

export default async function run({ statusCode, body }, ctx) {
  return result({ kind: "start", statusCode, body }, ctx);
}

